do $offering_readiness_projection$
declare
  targets constant jsonb:=$readiness_projection_targets$[{"oid":25750,"signature":"bx1_portal.offering_package_projection_pre_appointment(jsonb,uuid)","sha":"3af34c6fb9b6e51b37d6fdfbf25193f5c079d430f002a5d02186444ee917fe1e","metadata":{"oid":"25750","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"offering_package_projection_pre_appointment","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["c","target_product"],"proargtypes":["3802","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"original":"declare p bx1_portal.products; r bx1_portal.offering_revisions;\n  issuer bx1_portal.offering_decisions; compliance bx1_portal.offering_decisions;\n  can_issuer boolean; can_compliance boolean; is_ready boolean;\nbegin\n  select * into p from bx1_portal.products where id=target_product;\n  if p.id is null or p.current_offering_revision_id is null then return null; end if;\n  select * into r from bx1_portal.offering_revisions where id=p.current_offering_revision_id and product_id=p.id;\n  if r.id is null or r.origin<>'SUBMITTED' then return null; end if;\n  select * into issuer from bx1_portal.offering_decisions\n    where offering_revision_id=r.id and decision_kind='ISSUER';\n  select * into compliance from bx1_portal.offering_decisions\n    where offering_revision_id=r.id and decision_kind='COMPLIANCE';\n  can_issuer:=p.status in ('IN_REVIEW','APPROVED') and bx1_portal.offering_issuer_authorised(c,p.id)\n    and (compliance.id is null or bx1_portal.entity_people_independent(auth.uid(),compliance.actor_id));\n  can_compliance:=p.status='IN_REVIEW' and compliance.id is null\n    and bx1_portal.scoped_reviewer(c,(select reviewer_scope from bx1_portal.organisations where id=p.organisation_id),p.organisation_id)\n    and bx1_portal.entity_people_independent(auth.uid(),r.submitted_by)\n    and (issuer.id is null or bx1_portal.entity_people_independent(auth.uid(),issuer.actor_id));\n  is_ready:=bx1_portal.offering_operational(p.id);\n  return pg_catalog.jsonb_build_object(\n    'id',r.id,'package_number',r.package_number,'origin',r.origin,\n    'product_revision_at_submission',r.product_revision_at_submission,\n    'terms_hash',r.terms_hash,'document_hashes',r.document_hashes,\n    'common_envelope_hash',r.common_envelope_hash,'deployment_configuration_hash',r.deployment_configuration_hash,\n    'common_envelope',case when r.terms->'terms_version'='3'::jsonb then r.terms->'common_envelope' else null::jsonb end,\n    'deployment_configuration',case when r.terms->'terms_version'='3'::jsonb then r.terms->'deployment_configuration' else null::jsonb end,'submitted_at',r.submitted_at,\n    'issuer_status',coalesce(issuer.decision,'PENDING'),\n    'compliance_status',coalesce(compliance.decision,'PENDING'),\n    'issuer_review_notes',case when bx1_portal.scoped_operator(c,p.organisation_id)\n      or bx1_portal.scoped_reviewer(c,(select reviewer_scope from bx1_portal.organisations where id=p.organisation_id),p.organisation_id)\n      then issuer.notes end,\n    'issuer_review_checks',case when bx1_portal.scoped_operator(c,p.organisation_id)\n      or bx1_portal.scoped_reviewer(c,(select reviewer_scope from bx1_portal.organisations where id=p.organisation_id),p.organisation_id)\n      then issuer.checks else null end,\n    'technical_readiness_status','NOT_VERIFIED',\n    'status',case when issuer.decision='CHANGES_REQUIRED' or compliance.decision='CHANGES_REQUIRED' then 'CHANGES_REQUIRED'\n      when issuer.decision='APPROVED' and compliance.decision='APPROVED'\n        and bx1_portal.offering_approved(p.id) then 'APPROVED_AWAITING_READINESS'\n      when issuer.decision='APPROVED' and compliance.decision='APPROVED' then 'AUTHORITY_EXPIRED'\n      else 'IN_REVIEW' end,\n    'can_review_issuer',can_issuer,'can_review_compliance',can_compliance,\n    'publishable',p.status='APPROVED' and is_ready,\n    'subscribable',p.status='PUBLISHED' and is_ready) || case when exists(\n      select 1 from bx1_private.offering_document_profiles where offering_revision_id=r.id)\n      then pg_catalog.jsonb_build_object('document_evidence',bx1_private.offering_document_evidence_summary(r.id))\n      else '{}'::jsonb end;\nend","cuts":[{"name":"tagged_readiness","from":"is_ready:=bx1_portal.offering_operational(p.id);","to":"is_ready:=case when p.review_roleplay_policy_id is not null then\n    bx1_private.fund_roleplay_investor_operational(p.id,p.review_roleplay_policy_id,p.review_roleplay_epoch)\n    else bx1_portal.offering_operational(p.id) end;","count":1},{"name":"readiness_status","from":"'technical_readiness_status','NOT_VERIFIED'","to":"'technical_readiness_status',case when is_ready is true then 'VERIFIED' else 'NOT_VERIFIED' end","count":1}]},{"oid":29607,"signature":"bx1_portal.offering_workflow_package_projection_base(jsonb,uuid)","sha":"d537cf85b5b4ee8488c14cb5a30df9693ee36ccad9d264a5afe385e34125c6a5","metadata":{"oid":"29607","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"offering_workflow_package_projection_base","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["c","target_product"],"proargtypes":["3802","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"original":"declare p bx1_portal.products; r bx1_portal.offering_revisions;\n  issuer bx1_portal.offering_decisions; compliance bx1_portal.offering_decisions;\n  can_issuer boolean; can_compliance boolean; is_ready boolean;\nbegin\n  select * into p from bx1_portal.products where id=target_product;\n  if p.id is null or p.current_offering_revision_id is null then return null; end if;\n  select * into r from bx1_portal.offering_revisions where id=p.current_offering_revision_id and product_id=p.id;\n  if r.id is null or r.origin<>'SUBMITTED' then return null; end if;\n  select * into issuer from bx1_portal.offering_decisions\n    where offering_revision_id=r.id and decision_kind='ISSUER';\n  select * into compliance from bx1_portal.offering_decisions\n    where offering_revision_id=r.id and decision_kind='COMPLIANCE';\n  can_issuer:=p.status in ('IN_REVIEW','APPROVED') and bx1_portal.offering_workflow_issuer_authorised(c,p.id)\n    and (compliance.id is null or bx1_portal.offering_workflow_people_independent(auth.uid(),compliance.actor_id));\n  can_compliance:=p.status='IN_REVIEW' and compliance.id is null\n    and bx1_portal.offering_workflow_product_appointment_authorised(c,p.id,'ComplianceOfficer')\n    and bx1_portal.offering_workflow_people_independent(auth.uid(),r.submitted_by)\n    and (issuer.id is null or bx1_portal.offering_workflow_people_independent(auth.uid(),issuer.actor_id));\n  is_ready:=bx1_portal.offering_technical_ready(r.id) is true;\n  return pg_catalog.jsonb_build_object(\n    'id',r.id,'package_number',r.package_number,'origin',r.origin,\n    'product_revision_at_submission',r.product_revision_at_submission,\n    'terms_hash',r.terms_hash,'document_hashes',r.document_hashes,\n    'common_envelope_hash',r.common_envelope_hash,'deployment_configuration_hash',r.deployment_configuration_hash,\n    'common_envelope',case when r.terms->'terms_version'='3'::jsonb then r.terms->'common_envelope' else null::jsonb end,\n    'deployment_configuration',case when r.terms->'terms_version'='3'::jsonb then r.terms->'deployment_configuration' else null::jsonb end,'submitted_at',r.submitted_at,\n    'issuer_status',coalesce(issuer.decision,'PENDING'),\n    'compliance_status',coalesce(compliance.decision,'PENDING'),\n    'issuer_review_notes',case when (bx1_portal.offering_workflow_operator(c,p.organisation_id) or bx1_private.fund_roleplay_manager_current(c,p.id))\n      or bx1_portal.offering_workflow_product_appointment_authorised(c,p.id,'ComplianceOfficer')\n      then issuer.notes end,\n    'issuer_review_checks',case when (bx1_portal.offering_workflow_operator(c,p.organisation_id) or bx1_private.fund_roleplay_manager_current(c,p.id))\n      or bx1_portal.offering_workflow_product_appointment_authorised(c,p.id,'ComplianceOfficer')\n      then issuer.checks else null end,\n    'technical_readiness_status','NOT_VERIFIED',\n    'status',case when issuer.decision='CHANGES_REQUIRED' or compliance.decision='CHANGES_REQUIRED' then 'CHANGES_REQUIRED'\n      when issuer.decision='APPROVED' and compliance.decision='APPROVED'\n        and bx1_portal.offering_workflow_approved(p.id) then 'APPROVED_AWAITING_READINESS'\n      when issuer.decision='APPROVED' and compliance.decision='APPROVED' then 'AUTHORITY_EXPIRED'\n      else 'IN_REVIEW' end,\n    'can_review_issuer',can_issuer,'can_review_compliance',can_compliance,\n    'publishable',p.status='APPROVED' and is_ready,\n    'subscribable',p.status='PUBLISHED' and is_ready) || case when exists(\n      select 1 from bx1_private.offering_document_profiles where offering_revision_id=r.id)\n      then pg_catalog.jsonb_build_object('document_evidence',bx1_private.offering_document_evidence_summary(r.id))\n      else '{}'::jsonb end;\nend","cuts":[{"name":"readiness_status","from":"'technical_readiness_status','NOT_VERIFIED'","to":"'technical_readiness_status',case when is_ready is true then 'VERIFIED' else 'NOT_VERIFIED' end","count":1}]}]$readiness_projection_targets$::jsonb;
