rgdefaults":0}},{"oid":38341,"signature":"bx1_private.fund_roleplay_investor_operational(p_product uuid, p_policy uuid, p_epoch integer)","sha":"5107b4e646af2cea44a7597c487f6c79616512e0556ce463f66972a1308afc4a","metadata":{"oid":"38341","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"fund_roleplay_investor_operational","prorows":0,"pronargs":3,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_product","p_policy","p_epoch"],"proargtypes":["2950","2950","23"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"22414","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}}]$readiness_projection_dependencies$::jsonb;
  spec jsonb; dependency jsonb; cut jsonb; metadata jsonb;
  target oid; next_body text; restored text; definition text; stage integer;
  originals integer:=0; finals integer:=0;
begin
  if current_user<>'postgres' or session_user<>'postgres' or auth.uid() is not null
    or bx1_private.test_roleplay_environment() is not true
    or not exists(select 1 from bx1_portal.entry_configuration where singleton and environment='TESTNET') then
    raise exception 'offering_readiness_test_owner_without_claims_required' using errcode='42501';end if;
  if jsonb_array_length(targets)<>2 or jsonb_array_length(dependencies)<>14 then
    raise exception 'offering_readiness_exact_scope_required' using errcode='55000';end if;
  -- Complete preflight before either target is changed. Mixed/unknown baselines
  -- fail closed; successful repetition accepts only the exact two final bodies.
  for spec in select value from jsonb_array_elements(targets) loop
    target:=(spec->>'oid')::oid;
    select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=target;
    if pg_catalog.to_regprocedure(spec->>'signature') is distinct from target
      or metadata is null or metadata-'prosrc' is distinct from spec->'metadata'
      or encode(sha256(convert_to(spec->>'original','UTF8')),'hex') is distinct from spec->>'sha' then
      raise exception 'offering_readiness_target_pin_changed: %',target using errcode='55000';end if;
    next_body:=spec->>'original';
    for cut in select value from jsonb_array_elements(spec->'cuts') loop
      if (length(next_body)-length(replace(next_body,cut->>'from','')))/length(cut->>'from')<>1 then
        raise exception 'offering_readiness_forward_cut_not_unique: %',cut->>'name' using errcode='55000';end if;
      next_body:=replace(next_body,cut->>'from',cut->>'to');
    end loop;
    restored:=next_body;
    for cut in select value from jsonb_array_elements(spec->'cuts') with ordinality item(value,position) order by position desc loop
      if (length(restored)-length(replace(restored,cut->>'to','')))/length(cut->>'to')<>1 then
        raise exception 'offering_readiness_reverse_cut_not_unique: %',cut->>'name' using errcode='55000';end if;
      restored:=replace(restored,cut->>'to',cut->>'from');
    end loop;
    if restored is distinct from spec->>'original' then
      raise exception 'offering_readiness_inverse_changed' using errcode='55000';end if;
    if metadata->>'prosrc'=spec->>'original' then originals:=originals+1;
    elsif metadata->>'prosrc'=next_body then finals:=finals+1;
    else raise exception 'offering_readiness_unknown_source: %',target using errcode='55000';end if;
  end loop;
  if originals<>2 and finals<>2 then raise exception 'offering_readiness_partial_baseline' using errcode='55000';end if;
  for stage in 1..2 loop
    for dependency in select value from jsonb_array_elements(dependencies) loop
      select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=(dependency->>'oid')::oid;
      if metadata is null or metadata-'prosrc' is distinct from dependency->'metadata'
        or encode(sha256(convert_to(metadata->>'prosrc','UTF8')),'hex') is distinct from dependency->>'sha' then
        raise exception 'offering_readiness_dependency_changed: %',dependency->>'oid' using errcode='55000';end if;
    end loop;
    for spec in select value from jsonb_array_elements(targets) loop
      target:=(spec->>'oid')::oid;next_body:=spec->>'original';
      for cut in select value from jsonb_array_elements(spec->'cuts') loop
        next_body:=replace(next_body,cut->>'from',cut->>'to');
      end loop;
      select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=target;
      if stage=1 and metadata->>'prosrc'=spec->>'original' then
        definition:=pg_catalog.pg_get_functiondef(target);
        if (length(definition)-length(replace(definition,metadata->>'prosrc','')))/length(metadata->>'prosrc')<>1 then
          raise exception 'offering_readiness_definition_body_not_unique' using errcode='55000';end if;
        execute replace(definition,metadata->>'prosrc',next_body);
        select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=target;
      end if;
      if metadata is null or metadata-'prosrc' is distinct from spec->'metadata'
        or metadata->>'prosrc' is distinct from next_body then
        raise exception 'offering_readiness_target_preservation_failed: %',target using errcode='55000';end if;
    end loop;
  end loop;
end $offering_readiness_projection$;
